# 自动识别项目文件夹。
# 标准项目结构下，本文件位于 pvi-report-assistant/src/config.py。
CURRENT_FOLDER = Path.cwd().resolve()
PROJECT_FOLDER = Path(__file__).resolve().parents[1]
DATA_FOLDER = PROJECT_FOLDER / "data" / "raw"
SAMPLE_FOLDER = PROJECT_FOLDER / "data" / "sample"
OUTPUT_FOLDER = PROJECT_FOLDER / "output"

def find_project_folder() -> Path:
    candidates = []
    candidates.extend([CURRENT_FOLDER, *CURRENT_FOLDER.parents])

    drive_root = Path("/drive")
    if drive_root.exists():
        candidates.extend([
            drive_root,
            drive_root / "PVI每日管理",
            drive_root / "PVI每日管理" / "原始数据",
        ])

    candidates.append(Path.home() / "Desktop" / "PVI每日管理")

    for folder in candidates:
        if folder.name == "原始数据" and folder.exists():
            return folder.parent
        if (folder / "原始数据").exists():
            return folder

    return CURRENT_FOLDER

# 自动读取文件名以“保单汇总列表”开头的最新Excel
FILE_PATTERN = "保单汇总列表*.xlsx"
INPUT_FILE = None

def find_source_file() -> Path:
    if INPUT_FILE:
        return INPUT_FILE.expanduser().resolve()

    if os.getenv("PVI_USE_SAMPLE") == "1":
        sample_candidates = [
            path
            for path in SAMPLE_FOLDER.glob(FILE_PATTERN)
            if not path.name.startswith("~$")
        ]
        if sample_candidates:
            return max(sample_candidates, key=lambda path: path.stat().st_mtime).resolve()

    search_folders = []
    for folder in [DATA_FOLDER, PROJECT_FOLDER, CURRENT_FOLDER, Path("/drive")]:
        try:
            resolved = folder.resolve()
        except Exception:
            resolved = folder
        if resolved.exists() and resolved not in search_folders:
            search_folders.append(resolved)

    candidates = []
    for folder in search_folders:
        candidates.extend(
            path
            for path in folder.glob(FILE_PATTERN)
            if not path.name.startswith("~$")
        )
        raw_folder = folder / "原始数据"
        if raw_folder.exists():
            candidates.extend(
                path
                for path in raw_folder.glob(FILE_PATTERN)
                if not path.name.startswith("~$")
            )
        data_raw_folder = folder / "data" / "raw"
        if data_raw_folder.exists():
            candidates.extend(
                path
                for path in data_raw_folder.glob(FILE_PATTERN)
                if not path.name.startswith("~$")
            )

    if not candidates:
        sample_candidates = [
            path
            for path in SAMPLE_FOLDER.glob(FILE_PATTERN)
            if not path.name.startswith("~$")
        ]
        if sample_candidates:
            return max(sample_candidates, key=lambda path: path.stat().st_mtime).resolve()

        checked = "\n".join(str(folder) for folder in search_folders)
        raise FileNotFoundError(
            f"没有找到 {FILE_PATTERN}。\n"
            f"已经检查过这些位置：\n{checked}\n"
            "请确认左侧上传的文件名以‘保单汇总列表’开头，扩展名是 .xlsx。\n"
            f"线上 Demo 会在没有 raw 数据时尝试读取：{SAMPLE_FOLDER}"
        )

    return max(candidates, key=lambda path: path.stat().st_mtime).resolve()

